parameters.text:
=Prepare a job application coaching report for this candidate.

Candidate name: {{ $json.name }}
Job title: {{ $json.jobTitle }}

JOB DESCRIPTION:
{{ $json.jobDescription }}

CANDIDATE CV:
{{ $json.cvText }}

parameters.jsCode:
let report = String($json.output ?? '');

report = report
  .replace(/\\r\\n|\\n/g, '\n')
  .replace(/\\([\\`*_{}\[\]()#+\-.!|>])/g, '$1')
  .replace(/^```(?:markdown|md)?\s*\n/i, '')
  .replace(/\n```\s*$/, '');

return [{ json: { ...$json, report } }];
